<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Request,Response};use App\Repositories\{WorkflowRepository,SettingsRepository,StudentRepository,EmployeeRepository};
final class CertificatesController extends AdminPageController{private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}public function index(Request$r):Response{$i=$this->i();return$this->renderPage('certificates',['certificates'=>(new WorkflowRepository($this->app->database()))->certificates($i),'students'=>(new StudentRepository($this->app->database()))->paginate($i,'',null,100),'employees'=>(new EmployeeRepository($this->app->database()))->all($i)]);}public function store(Request$r):Response{$type=(string)$r->input('recipient_type');try{(new WorkflowRepository($this->app->database()))->createCertificate($this->i(),(string)$r->input('template_id'),$type,(int)$r->input('student_id')?:null,(int)$r->input('staff_id')?:null,(string)$r->input('date'),(int)user()['id'],(string)$r->input('achievement')?:null);}catch(\DomainException$e){return Response::html(e($e->getMessage()),422);}return Response::redirect(url('/admin/certificates'));}public function delete(Request$r):Response{if(!(new WorkflowRepository($this->app->database()))->deleteCertificate($this->i(),(int)$r->route('id')))return Response::html('Certificate not found',404);return Response::redirect(url('/admin/certificates'));}}
